(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fil"] = {"ui":{"skip":"Lumaktaw sa nilalaman","back":"← Bumalik sa AI-gile","lang.button":"Wika: {name}","lang.dialog":"Pumili ng wika","lang.search":"Maghanap ng wika","lang.none":"Walang wikang tumutugma","lang.notYet":"Hindi pa naisasalin ang {name}","theme.aria":"Magpalit sa pagitan ng maliwanag at madilim na tema","theme.toLight":"Lumipat sa maliwanag na tema","theme.toDark":"Lumipat sa madilim na tema","words.underline":"I-underline ang mga salitang ito sa page","words.underlineHelp":"I-hover o i-tap ang salitang may tuldok-tuldok para makita kung ano ang ibig sabihin nito.","index.title":"AI-gile: ang AI dev team mo, sa iisang board","index.description":"Ang AI-gile ay kanban board para sa mga AI coding team. Nagtatrabaho sila habang natutulog ka; isang maikling tambak lang ang haharapin mo: mga desisyon, susubukan at aaprubahan.","hero.logoAlt":"Icon ng AI-gile board","hero.h1.html":"Ang AI dev team mo, sa iisang&nbsp;board.","hero.alpha":"🐣 Saradong pre-alpha","hero.alphaTitle":"Maaga pa at hindi pa tapos: salamat sa pagsubok!","hero.lede":"Gumagawa sila habang natutulog ka. Paggising mo, may isang maikling tambak: ilang tanong, ilang susubukan, isa o dalawang purple na diamond. I-click, aprubahan, balik sa kape mo.","dl.windows":"Windows app","dl.browser":"Gamitin sa browser","dl.soon":"Malapit na","dl.notify":"🔔 Sabihan ako kapag bukas na","dl.notifySmall":"Alpha o beta","hero.secondary":"Agile, pero hindi kailanman nangangailangan ng stand-up na kape ang team. (Nagsta-stand-up pa rin naman sila.)","pitch.h2":"Ang AI-gile sa dami ng salitang gusto mo","pitch.lede":"Pumili ng haba, mula isang salita hanggang 144. Bawat haba ay sariling paglalarawan, isinulat para sa laki nito. I-drag ang slider o gamitin ang mga arrow key.","pitch.rangeLabel":"Haba sa bilang ng salita","pitch.dice":"🎲 ibang bersyon","pitch.words.one":"{n} salita","pitch.words.other":"{n} salita","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letra","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} card sa board ngayon","count.line.html.other":"{n} card sa board ngayon","features.aria":"Ano ang ginagawa nito","f.pile.h":"Isang tambak para sa iyo","f.pile.html":"Dito sa <b>Para sa iyo</b> nakalagay ang lahat ng naghihintay sa iyo, sa lahat ng project: mga tanong, mga susubukan, mga gawaing tao lang ang makakagawa. Sinasabi ng pila mo kung ano ang susunod at gaano ito katagal.","f.sleep.h":"Mga team na nagtatrabaho habang natutulog ka","f.sleep.p":"May lead at team ng mga AI agent ang bawat project. Mag-comment sa isang card at gigising ang team, gagawin ang trabaho, at ibabalik ito na may mga hakbang na masusundan kahit ng pagod na tao.","f.tester.h":"Unang sumusuri ang AI tester","f.tester.p":"Bago may makarating sa iyo, sinusundan ng tester ang mga hakbang sa kopya ng app at ipinapakita ang nakita niya, may screenshot. Tingnan nang mabilis ang mga pumasa at aprubahan sa isang click.","f.proof.h":"Patunay, hindi pangako","f.proof.p":"Ipinapakita ng bawat pasa kung ano ang nagbago: ang mga file, ang diff, ang mga screenshot. Hindi mo na kailangang buksan ang bawat app para malaman kung tapos na.","f.chat.h":"Makipag-chat sa mga lead mo","f.chat.p":"Riles na parang Discord: isang icon bawat project, purple na diamond para sa nangangailangan ng pansin mo. Magpadala ng idea sa lead; gagawin niya itong mga card at plano, may ✅ Go na button.","f.tidy.h":"Nag-aayos nang sarili","f.tidy.p":"Nagsasama ang magkakaugnay na card, naaayos ang magulong pamagat, at pinapanatiling magaan ng token check ang code. Mas kaunting pagpapalit-palit, mas kaunting iisipin.","f.private.h":"Sa iyo, sa computer mo","f.private.li1":"Tumatakbo ang board sa sarili mong makina at ikaw lang ang sinasagot.","f.private.li2":"End-to-end encrypted ang mga pribadong DM sa pagitan ng mga tao.","f.private.li3":"Walang account, walang tracker, walang cookie.","f.lang.h":"Sa wika mo","f.lang.p":"Mahigit 120 wika, mula Dutch, Welsh at Japanese hanggang pirate, Yoda at Klingon, may mabilis na balik sa English para sa mga salita ng developer.","tl.aria":"Timeline mula sa unang usapan hanggang sa roadmap","tl.h2":"Mula sa unang chat hanggang sa susunod","tl.lede":"Totoong petsa at oras, sa sarili mong time zone. Pagkatapos ng ngayon, plano na ito, walang pinangakong petsa.","tl.today":"Ngayon","tl.planned":"planado","tl.cards.one":"{n} card","tl.cards.other":"{n} card","join.h2":"Sumali ka","join.lede":"Ginagawa ang AI-gile ng isang maliit na tao at napakaraming matiyagang agent. Pribado pa ito sa ngayon, sa saradong alpha kasama ang mga kaibigan. Gusto mo bang sumubok kapag nagbukas na ito?","join.btn":"Magpahayag ng interes","join.small":"Mag-e-email lang kami, wala nang iba","footer.tag":"AI-gile. Walang tracker, walang cookie, walang stand-up na kape.","footer.licence":"Lisensya para sa negosyo","footer.status":"Status","footer.privacy":"Ano ang iniimbak namin","form.sending":"Ipinapadala…","form.failed":"Hindi iyon umubra: subukan ulit mamaya.","form.offline":"Hindi maabot ang AI-gile: subukan ulit mamaya.","form.keep":"Ginagamit lang namin ito para sumagot sa iyo, saka namin ito buburahin. Walang tracker, walang cookie.","form.keepLink":"Ano ang iniimbak namin","interest.title":"AI-gile: sabihan ako kapag nagbukas ang alpha","interest.description":"Iwan ang email mo para malaman kapag nagbukas ang saradong alpha o beta ng AI-gile.","interest.h1":"🔔 Sabihan ako kapag bukas na","interest.lede":"Nasa saradong pre-alpha ang AI-gile. Iwan ang email mo at susulatan ka namin nang isang beses, kapag may lugar na para sa iyo.","interest.email":"Ang email mo","interest.which":"Aling pagsubok?","interest.alpha":"Saradong alpha: maaga, magaspang, maraming pagbabago","interest.beta":"Beta: mas matatag, mas huli","interest.both":"Alinman, kung ano ang mauna","interest.submit":"Ilagay mo ako sa listahan","interest.thanks":"Salamat! Nasa listahan ka na.","licence.title":"AI-gile: lisensya para sa negosyo","licence.description":"Ginagamit ang AI-gile sa negosyo mo? Mag-apply para sa libreng lisensya para sa negosyo.","licence.h1":"📜 Lisensya para sa negosyo","licence.lede":"Ginagamit ang AI-gile sa trabaho? Sabihin kung sino kayo at ano ang ginagawa ninyo. Kung nakakatulong ito sa kapwa, libre ang lisensya.","licence.company":"Kumpanya","licence.website":"Website","licence.what":"Ano ang ginagawa ninyo","licence.how":"Paano ito nakakatulong sa mundo","licence.email":"Email","licence.submit":"Mag-apply","licence.thanks":"Salamat! Sasagot kami sa email.","status.title":"Status ng AI-gile","status.h1":"Status ng AI-gile","status.quiet":"Tahimik ang lahat","status.intro":"Gumagana ba ang AI-gile ngayon? Tinitingnan ng page na ito ang website, ang pag-share ng board, ang mga tawag at ang download kada 5 minuto.","status.up":"Gumagana (sumagot sa loob ng {ms} ms)","status.slow":"Hindi sumagot sa huling check, sinusubukan ulit","status.down":"Down: hindi sumagot sa huling dalawang check","status.svc.web":"Website","status.svc.web.offers":"Ang site na ito: kung ano ang AI-gile, at ang interest form","status.svc.boards":"Pag-share ng board","status.svc.boards.offers":"Mga pampublikong board, mga mensahe sa pagitan ng magkakaibigan at mga imbitasyon","status.svc.calls":"Mga tawag","status.svc.calls.offers":"Boses, video at screen share sa AI-gile","status.svc.download":"Download","status.svc.download.offers":"Ang Windows installer at mga invite link","status.checking":"Sinusuri…","status.offline":"Hindi maabot ang status service ngayon (susubukan ulit)","status.updated":"na-update {ago}","status.justNow":"ngayon lang","status.min":"{n} min ang nakalipas","status.hours":"{n} oras ang nakalipas","status.days":"{n} araw ang nakalipas","privacy.title":"AI-gile: ano ang iniimbak namin","privacy.h1":"Ano ang iniimbak namin","privacy.lede":"Sa madaling salita: ang ipinapadala mo lang sa amin, at hindi nang matagal.","privacy.only":"Ang ipinapadala mo lang sa amin: ang tina-type mo sa isang form, gaya ng email mo. Wala nang iba tungkol sa iyo.","privacy.sealed":"Sine-seal ito para hindi ito mabasa ng server namin: sa browser mo bago ito umalis (sa mas lumang browser, sa sandaling dumating ito). Ang sarili lang naming board ang makakapagbukas nito.","privacy.server":"Binubura ito sa server sa sandaling makarating ito sa board namin. Anumang naroon pa rin pagkalipas ng 30 araw ay binubura rin.","privacy.board":"Iniimbak lang namin ito sa board namin hanggang makasagot kami sa iyo, saka namin ito buburahin doon din.","privacy.none":"Walang tracker, walang cookie, walang analytics.","privacy.local":"Ang wika mo at ang pinili mong light o dark ay nananatili sa sarili mong browser. Hindi kailanman ipinapadala sa amin ang mga ito.","privacy.ask":"Gusto mo bang mabura ito nang mas maaga? Sumagot ka lang sa email namin at sabihin mo.","live.h2":"Panoorin itong binubuo, live","live.caption":"Nakatago ang bawat card: makikita mo ang hugis ng gawain, hindi ang mga salita.","live.watching.one":"live: {n} ang nanonood","live.watching.other":"live: {n} ang nanonood","live.last.now":"Kalilipat lang ng huling card","live.last.min.one":"Nailipat ang huling card {n} min ang nakalipas","live.last.min.other":"Nailipat ang huling card {n} min ang nakalipas","live.last.hour.one":"Nailipat ang huling card {n} oras ang nakalipas","live.last.hour.other":"Nailipat ang huling card {n} oras ang nakalipas","live.last.day.one":"Nailipat ang huling card {n} araw ang nakalipas","live.last.day.other":"Nailipat ang huling card {n} araw ang nakalipas","live.offline":"Nagpapahinga muna ang live board. Balik ka ulit mamaya.","live.cols":"Backlog|Gagawin|Ginagawa|Chine-check ng team|Para sa iyo na i-test|Para sa team|Tapos na"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Naipasa."]},{"n":2,"texts":["Kanban, robot.","Agent, organisado.","Ginawang idea."]},{"n":3,"texts":["Kanban para sa robot.","Idea, ginagawang feature.","Libreng kanban ng agent."]},{"n":5,"texts":["Kanban board na pinapatakbo ng agent.","Ikaw ang nagsusulat, agent ang gumagawa.","Libre, lokal, sinubok, medyo kalokohan."]},{"n":8,"texts":["Libreng kanban board kung saan nagtatrabaho ang mga AI agent.","Magsulat ng idea. Gagawin ito ng agent. Ikaw ang aaprub.","Agile para sa isang tao at maraming matiyagang robot."]},{"n":13,"texts":["Kanban board sa computer mo kung saan kinukuha ng mga AI agent ang mga card.","Magsulat ng idea. Gagawin ito ng team ng agent. Susuriin ito ng tester.","Libre, walang account, walang tracker: isang board, ilang robot, at ikaw ang masusunod."]},{"n":21,"texts":["Ang AI-gile ay kanban board para makatrabaho ang mga AI coding agent. Sila ang kumukuha ng mga card; ikaw ang sumusubok at nag-aaprub.","Bawat project ay may lead at team ng mga AI agent. Mag-comment sa kahit anong card at magsisimulang magtrabaho ang team.","Libre at personal na to-do board na tumatakbo sa sarili mong computer. Mga robot ang gumagawa. Ikaw ang nagsasabi ng oo."]},{"n":34,"texts":["Ilalagay mo ang mga idea sa board. Gagawin ng team ng mga AI agent ang mga ito bilang gumaganang feature, susubukan, at ibabalik sa iyo na may mga hakbang na masusubukan mo. Walang matatapos hangga't hindi mo sinasabi.","Gawang-bahay na kanban board ang AI-gile na binuo ni Rich sa tulong ng napakaraming agent na ngayon ay pinamamahalaan nito. Libre ito, tumatakbo sa computer mo, at ibinabahagi sa mga kaibigan, hindi ibinebenta.","Isipin ang karaniwang kanban board, may mga column mula Backlog hanggang Tapos na, maliban na ang mga card ay kinukuha ng mga AI agent. Nag-uulat sila ng progreso, nagtatanong kapag naipit, at laging naghihintay ng pagsang-ayon mo."]},{"n":55,"texts":["Ang AI-gile ay kanban board na ang team ay binubuo ng mga AI agent. May lead ang bawat project na nagpaplano ng trabaho at mga katulong na gumagawa nito. Kapag handa na ang isang feature, sinusubukan ito ng AI tester at kumukuha ng screenshot, saka ito mapupunta sa tambak mo. Aprubahan ito, o mag-comment at gagawin nila ulit.","Nagsimula ito bilang paraan ng isang tao para masubaybayan ang maraming AI coding session nang sabay-sabay, at lumaki bilang tunay na board. Tumatakbo ito sa makina mo, walang account na kailangan, at walang tracker. Libre ito para sa mga kaibigan at sa mga curious. Hindi pa ito tapos, kaya asahan ang ilang gaspang at paminsan-minsang sorpresa.","Heto ang tapat na bersyon. Ikaw pa rin ang kailangang mag-isip ng mga idea, at ikaw pa rin ang kailangang tumingin sa mga resulta. Ang ginagawa ng AI-gile ay lahat ng nasa pagitan: pinapanatili nitong maayos ang mga card, ginigising ang tamang agent kapag nag-comment ka, ipinapakita kung ano mismo ang nagbago, at inilalagay ang lahat sa isang maikling tambak para sa iyo."]},{"n":89,"texts":["Ang AI-gile ay libreng kanban board na pinapatakbo mo sa sarili mong computer. Sa halip na mga tao, bawat project ay may team ng mga AI agent: isang lead na ginagawang mga card at plano ang mga idea mo, at mga katulong na kumukuha ng mga card ayon sa priyoridad. Kapag may nabuo na, sinusundan ng AI tester ang mga hakbang sa pagsubok at ipinapakita sa iyo ang nakita nito. Pagkatapos ay maghihintay ito sa isang tambak na tinatawag na Para sa iyo. Aprubahan mo, o mag-comment ka at susubukan ulit ng team. Walang makakarating sa Tapos na nang hindi ikaw ang nagpapasya.","Ilang feature na hindi mo marahil inaasahan. Pinupunan ng night watch ang column na Gagawin habang natutulog ka, at pumipili ito ng mga card na hindi nangangailangan ng sagot mo. Ipinapakita ng token counter kung gaano na ang nagamit ng mga agent ngayong araw at ngayong linggo, at sinasabihan sila ng No Token Mode na tumigil sa paggastos. Puwede kang magpadala ng mensahe sa mga kaibigan, at end-to-end encrypted ang mga pribadong mensahe. Nagsasalita ang board ng halos 120 wika, kasama ang Dutch, Flemish, pirate at Klingon. Wala ni isang sentimo ang babayaran dito, at walang nagtatangkang magbenta nito sa iyo.","Maliit at personal na proyekto ang AI-gile, hindi kumpanya. Gusto ni Rich na mabantayan ang ilang AI coding project nang hindi binubuksan ang bawat app para silipin ang mga ito, kaya gumawa sila ng board para rito ng mga agent, at ginamit nila ang board para buuin ang iba pang bahagi nito. Nasa saradong pre-alpha ito, ibig sabihin gumagana ito, kadalasan, para sa iilang kaibigan. Walang pricing page, walang newsletter at walang plano sa paglago. Kung mukha itong makakatulong, puwede kang humiling na subukan ito kapag mas nagbukas na ito."]},{"n":144,"texts":["Ang AI-gile ay kanban board para sa isang tao at maraming AI agent. Tumatakbo ito sa sarili mong computer at ganap na libre. Magdadagdag ka ng mga project, at bawat project ay magkakaroon ng lead at maliit na team. Makikipag-chat ka sa lead, medyo parang Discord, at ilalarawan mo ang isang idea; gagawin ito ng lead na mga card at plano, saka maghihintay na pindutin mo ang Go. Gagawin ng team ang mga card ayon sa priyoridad, gamit ang simpleng command line na ginawa para sa mga language model. Bago may bumalik sa iyo, susundan ng AI tester ang mga hakbang sa kopya ng app at maglalakip ng screenshot. Mapupunta sa tambak mo ang natapos na trabaho kasama ang mga nabagong file at ang diff. Aprubahan mo, o mag-iwan ka ng comment at gigising ang team at susubukan ulit. Ikaw lang ang puwedeng maglipat ng card sa Tapos na.","Isang araw kasama ang AI-gile, halos ganito. Sa gabi, mag-iiwan ka ng ilang comment: mali ang lugar ng buton na ito, dapat naka-sort ang listahang iyon, puwede bang magkaroon ng dark mode. Matutulog ka na. Babasahin ng mga agent ang mga comment, gagawin ang mga pagbabago, susubukan ang mga ito at ibabalik sa iyo. Kung maubusan ang Gagawin, pupunuin ito ng night watch mula sa backlog ng mga card na hindi nangangailangan ng sagot mo. Sa umaga, may isang maikling tambak: ilang tanong at ilang susubukan, bawat isa ay may mga hakbang na masusundan ng inaantok na tao at screenshot na gumagana ito. Magki-click ka, aaprubahan ang magaganda, at ibabalik ang iba. Ipinapakita ng token counter kung ano ang nagamit ng lahat ng ito, at nandiyan ang No Token Mode para sa mga mahigpit na linggo. Pagkatapos ay mag-aalmusal ka, na hindi pa kayang tulungan ng mga agent.","Una, kung ano ang hindi AI-gile. Hindi ito startup, hindi ito ibinebenta, at walang kumukuha ng data mo. Libreng board ito na tumatakbo sa computer mo, walang account, walang tracker at walang cookie. Ito naman ang AI-gile: isang maayos na lugar para makita ang bawat AI coding project nang sabay-sabay, may team ng mga agent na gumagawa ng mga card at ikaw ang nagpapasya. Pinagsasama nito ang magkakaugnay na card, inaayos ang magulong pamagat, at binabantayan kung nananatiling magaan ang code. Nagsasalita ito ng halos 120 wika, mula Dutch at Flemish hanggang pirate at Klingon. Puwedeng magpadala ng mensahe ang magkakaibigan sa isa't isa, pribado at naka-encrypt. Binuo ito ni Rich at ng napakaraming matiyagang agent, kadalasan sa pamamagitan ng paggamit dito mismo. Nasa saradong pre-alpha ito, kaya may gaspang pa sa ilang bahagi. Kung mukhang masaya, magtanong nang magalang at baka makapasok ka nang maaga."]}],"quips":{"1":"Isang salita. Matapang. Baka sobra pa.","3":"Tatlong salita. Mas tapat na kaysa sa karamihan ng product page.","8":"Walong salita. Mas maikli pa sa isang stand-up.","21":"Nga pala, story point ang mga haba. Siyempre naman.","55":"Limampu't limang salita. Dalawang card ang natapos habang binabasa mo iyan.","144":"Iyan ang mahaba. Walang 233. Natulog na ang mga agent."}},"timeline":{"first-idea.name":"Ang unang idea","first-idea.line":"Ang pinakaunang usapan, bago pa magkaroon ng anumang code.","first-board.name":"Unang board","first-board.line":"Board na sinusubaybayan ang sarili nitong pagbuo: mga card, column, drag and drop, mga project.","team-roles.name":"Team at mga role","team-roles.line":"Mga profile ng agent, template ng team, mga space at kung sino ang gumagawa ng ano.","install.name":"Pag-install at mga release","install.line":"Zip na kayang i-install ng kaibigan, self-update, mga channel at pag-roll back.","usage-saver.name":"Pagtitipid sa gamit","usage-saver.line":"Sukatin ang gastos ng bawat takbo, panatilihing magaan ang code, protektahan ang limit mo.","friends.name":"Mga kaibigan at pagbabahagi","friends.line":"Mga pribadong DM, ginulong relay, mga imbitasyon, mga role at pinagsasaluhang project.","languages.name":"Mga wika","languages.line":"Bawat teksto sa screen ay nasa language file, Dutch at Flemish muna.","ai-tester.name":"AI tester","ai-tester.line":"Sinusuri muna ng tester ang bawat pasa at ipinapakita ang nakita niya.","website.name":"Ang website","website.line":"Ang aigile.lol, ang teaser at ang timeline na ito.","streaming.name":"Chat at streaming","streaming.line":"Discord, Twitch, OBS, streamer mode, mga GIF at emoji.","no-ai.name":"Edisyong walang AI","no-ai.line":"Board para sa mga nagko-code nang walang AI, at mga pampublikong board.","night-watch.name":"Night watch","night-watch.line":"Isang bantay at Scrum Master ang nagpapanatili sa mga team sa gawain habang natutulog ka.","p-more.name":"Lahat ng iba pa","p-more.line":"Mas maliliit na idea na naghihintay pa ng turn nila.","p-android.name":"Telepono at Android","p-android.line":"Maabot ang board mo mula sa telepono, tapos native na Android app.","p-release.name":"Alpha at higit pa","p-release.line":"Saradong alpha, ang live na site, tapos beta.","p-languages.name":"Higit pang wika","p-languages.line":"Mahigit isandaang wika, at immersion mode para sa mga nag-aaral.","p-engines.name":"Higit pang AI engine","p-engines.line":"Pumili ng Claude, Codex o Gemini para sa bawat agent.","p-pro.name":"Propesyonal na gawi","p-pro.line":"Mga risk label, merge gate, mga incident card at mga guard rail.","p-self.name":"Pag-aalaga sa iyo","p-self.line":"Tired mode, mga paalala sa self-care at 4:20.","p-servers.name":"Mga server at paglaki","p-servers.line":"Pangkalahatang setting ng server, mga role at pagpaplano para sa paglago.","p-livestream.name":"Mga dagdag sa streaming","p-livestream.line":"Twitch chat, custom na emoji at pampublikong live view."},"words":{"button":"📖 Mga dev word","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Maghanap ng salita…","none":"Walang salitang tumutugma.","close":"Isara","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Ang folder ng code ng project at ang buong history ng mga commit nito, na karaniwang nasa GitHub din.","also":["repo","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Hiwalay na linya ng trabaho sa code, para makapagbago nang hindi ginagalaw ang pangunahing bersyon.","also":["branch","mga branch"]},{"id":"commit","g":"build","word":"Commit","text":"Naka-save na snapshot ng code, na may maikling note kung ano ang nagbago. Puwede kang laging bumalik sa isa.","also":["commit","mga commit"]},{"id":"push","g":"build","word":"Push","text":"Pagpapadala ng mga naka-save na snapshot (commit) mula sa computer na ito pataas sa GitHub, para ma-back up at maibahagi."},{"id":"merge","g":"build","word":"Merge","text":"Pagsasama ng mga pagbabago ng isang branch pabalik sa pangunahing bersyon."},{"id":"pr","g":"build","word":"Pull request","text":"Paghiling na i-check ang mga pagbabago ng isang branch at i-merge sa pangunahing bersyon.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Pag-aayos ng code nang hindi binabago ang ginagawa nito: mas maliliit na file, mas malilinaw na pangalan, mas kaunting pag-uulit."},{"id":"bug","g":"build","word":"Bug","text":"Isang bagay na hindi gumagana nang tama.","also":["bug","mga bug"]},{"id":"test","g":"build","word":"Test","text":"Pagsubok sa natapos na trabaho para tiyaking ginagawa nito ang hiniling, bago mo ito tanggapin.","also":["test","mga test"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Pagpapa-live ng bagong bersyon, halimbawa sa server na ginagamit ng mga tao."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Mga idea at trabahong hindi pa naipaplano. Walang gagawin dito hangga't hindi ito nalilipat sa Gagawin."},{"id":"sprint","g":"team","word":"Sprint","text":"Maikling yugto ng trabaho (madalas isa o dalawang linggo) na may napagkasunduang set ng mga card na tatapusin.","also":["sprint","mga sprint"]},{"id":"standup","g":"team","word":"Stand-up","text":"Mabilis na check-in: ano ang ginawa ng bawat miyembro, ano ang susunod nilang gagawin, at ano ang humahadlang sa kanila.","also":["standup","stand-up","mga stand-up"]},{"id":"kanban","g":"team","word":"Kanban","text":"Board na may mga column (Gagawin, Ginagawa, Tapos na) kung saan lumilipat pakanan ang mga card habang umuusad ang trabaho."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: ang pinakamaraming card na dapat hawakan ng isang column, para tapusin muna ng team ang mga bagay bago magsimula ng iba.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI na kusang gumagawa ng isang task: binabasa ang code, gumagawa ng pagbabago, nagpapatakbo ng check, at nag-uulat pabalik.","also":["agent","mga agent"]},{"id":"token","g":"team","word":"Token","text":"Ang yunit na ginagamit sa pagbilang ng paggamit ng AI: halos ilang letra ng text na binabasa o isinusulat. Mas kaunting token, mas maraming natitira sa plan mo.","also":["token","mga token"]},{"id":"hook","g":"team","word":"Hook","text":"Maliit na command na kusang tumatakbo sa takdang sandali, hal. kapag nagsimula ang AI session, para marinig ng team ang mga comment mo.","also":["hook","mga hook"]}]}};
